"},"$:/plugins/rimir/work-focus/check.js":{"title":"$:/plugins/rimir/work-focus/check.js","text":"/*\
title: $:/plugins/rimir/work-focus/check.js
type: application/javascript
module-type: library

The work-focus check: runs every area filter once (first match wins), applies
mutes and writes one snapshot tiddler. Never runs on wiki change events.

\*/
"use strict";

var dates = require("$:/plugins/rimir/work-focus/dates.js");
var Widget = require("$:/core/modules/widgets/widget.js").widget;

var SNAPSHOT = "$:/temp/rimir/work-focus/snapshot";
var ACTED = "$:/temp/rimir/work-focus/acted";
var MUTES = "$:/rimir/work-focus/mutes";
var AREA_TAG = "$:/tags/rimir/work-focus/area";
var GLOBAL_IMPORT = "\\import [subfilter{$:/core/config/GlobalImportFilter}]\n";

exports.SNAPSHOT = SNAPSHOT;
exports.ACTED = ACTED;
exports.MUTES = MUTES;
exports.AREA_TAG = AREA_TAG;

// Area titles in tag order (drafts left out).
exports.areas = function(wiki) {
	return wiki.filterTiddlers("[all[shadows+tiddlers]tag[" + AREA_TAG + "]!is[draft]]");
};

// A widget under an `\import` pragma (e.g. "\\import <filter>\n"): filters run under it, or under
// a widget parented on it, see the imported functions and macros.
exports.importWidget = function(wiki, pragma, parent) {
	var parser = wiki.parseText("text/vnd.tiddlywiki", pragma, {parseAsInline: true}),
		widget = wiki.makeWidget(parser, {parentWidget: parent || $tw.rootWidget, document: $tw.fakeDocument});
	widget.render($tw.fakeDocument.createElement("div"), null);
	// the innermost widget is the importvariables widget carrying the imports; variables are
	// looked up from the parent, so hand out a child of it
	while(widget.children && widget.children.length) {
		widget = widget.children[0];
	}
	return new Widget({}, {wiki: wiki, parentWidget: widget, document: $tw.fakeDocument});
};

// A widget that sees the global functions and macros, imported the way the page template does
// (`\import [subfilter{$:/core/config/GlobalImportFilter}]`), so area and action filters can call
// `$:/tags/Global` functions.
exports.globalWidget = function(wiki, parent) {
	return exports.importWidget(wiki, GLOBAL_IMPORT, parent);
};

// Run a filter; never throws. Returns {list, error}: error is the message when the filter threw
// or reported a runtime error ("Filter error: ..." / "Filter Error: ..."), list is then empty.
exports.runFilter = function(wiki, filter, widget, source) {
	var list;
	try {
		list = wiki.filterTiddlers(filter, widget, source);
	} catch(e) {
		return {list: [], error: String(e && e.message || e)};
	}
	if(list.length && /^filter error:/i.test(String(list[0]))) {
		return {list: [], error: String(list[0])};
	}
	return {list: list, error: null};
};

// Mutes still in force: value is a day after today.
exports.activeMutes = function(wiki, now) {
	var data = wiki.getTiddlerData(MUTES, {}), result = {};
	Object.keys(data).forEach(function(item) {
		var days = dates.daysFrom(data[item], now);
		if(days !== null && days > 0) {
			result[item] = String(data[item]).trim();
		}
	});
	return result;
};

exports.compute = function(wiki, now) {
	var mutes = exports.activeMutes(wiki, now),
		snapshot = {checked: $tw.utils.stringifyDate(now), areas: {}, muted: [], errors: {}},
		claimed = Object.create(null),
		widget = exports.globalWidget(wiki);
	exports.areas(wiki).forEach(function(area) {
		var filter = wiki.getTiddler(area).fields["wf.filter"] || "", found = [],
			result = exports.runFilter(wiki, filter, widget);
		if(result.error) {
			snapshot.errors[area] = result.error;
		}
		result.list.forEach(function(item) {
			var tiddler = wiki.getTiddler(item);
			if(tiddler && tiddler.fields["draft.of"]) {
				// a draft is never an item
				return;
			}
			if(Object.prototype.hasOwnProperty.call(mutes, item)) {
				if(snapshot.muted.indexOf(item) === -1) {
					snapshot.muted.push(item);
				}
			} else if(!claimed[item]) {
				claimed[item] = true;
				found.push(item);
			}
		});
		snapshot.areas[area] = found;
	});
	return snapshot;
};

exports.write = function(wiki, now, opts) {
	opts = opts || {};
	var data = wiki.getTiddlerData(MUTES, null), active;
	if(data) {
		active = exports.activeMutes(wiki, now);
		if(Object.keys(active).length !== Object.keys(data).length) {
			wiki.setTiddlerData(MUTES, active);
		}
	}
	var snapshot = exports.compute(wiki, now);
	wiki.setTiddlerData(SNAPSHOT, snapshot);
	if(opts.clearActed) {
		wiki.deleteTiddler(ACTED);
	}
	if(opts.acted) {
		var acted = wiki.getTiddlerData(ACTED, {});
		acted[opts.acted.item] = {area: opts.acted.area, mark: opts.acted.mark};
		wiki.setTiddlerData(ACTED, acted);
	}
	return snapshot;
};
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/work-focus/click-outside.js":{"title":"$:/plugins/rimir/work-focus/click-outside.js","text":"/*\
title: $:/plugins/rimir/work-focus/click-outside.js
type: application/javascript
module-type: startup

Closes the work-focus panel on a click outside dock and panel, like TW popups:
the click is not swallowed and still reaches what is underneath.

\*/
"use strict";

var OPEN = "$:/temp/rimir/work-focus/open";

exports.name = "work-focus-click-outside";
exports.platforms = ["browser"];
exports.after = ["startup"];
exports.synchronous = true;

exports.startup = function() {
	// capture phase: runs even if a handler underneath stops propagation
	document.addEventListener("click", function(event) {
		var target = event.target;
		if($tw.wiki.getTiddlerText(OPEN) !== "yes" || (target && target.closest && target.closest(".wf-dock, .wf-panel"))) {
			return;
		}
		$tw.wiki.deleteTiddler(OPEN);
	}, true);
};
","type":"application/javascript","module-type":"startup"},"$:/config/rimir/work-focus/date-format":{"title":"$:/config/rimir/work-focus/date-format","text":"YYYY0MM0DD
"},"$:/config/rimir/work-focus/enabled":{"title":"$:/config/rimir/work-focus/enabled","text":"yes
"},"$:/config/rimir/work-focus/position":{"title":"$:/config/rimir/work-focus/position","text":"top-left
"},"$:/config/rimir/work-focus/section-limit":{"title":"$:/config/rimir/work-focus/section-limit","text":"5
"},"$:/plugins/rimir/work-focus/date-operators.js":{"title":"$:/plugins/rimir/work-focus/date-operators.js","text":"/*\
title: $:/plugins/rimir/work-focus/date-operators.js
type: application/javascript
module-type: filteroperator

Filter operators wf-date and wf-days.
  [wf-date[<expr>],[<sample>]]  one date string (empty when expr is unknown)
  [<dates>wf-days[]]            whole days from today per input; unparsable dropped

\*/
"use strict";

var dates = require("$:/plugins/rimir/work-focus/dates.js");

exports["wf-date"] = function(source, operator, options) {
	var d = dates.resolve(operator.operands && operator.operands.length ? operator.operands[0] : operator.operand, new Date());
	return d ? [dates.format(d, operator.operands ? operator.operands[1] : "", options.wiki)] : [];
};

exports["wf-days"] = function(source, operator, options) {
	var results = [], now = new Date();
	source(function(tiddler, title) {
		var n = dates.daysFrom(title, now);
		if(n !== null) {
			results.push(String(n));
		}
	});
	return results;
};
","type":"application/javascript","module-type":"filteroperator"},"$:/plugins/rimir/work-focus/dates.js":{"title":"$:/plugins/rimir/work-focus/dates.js","text":"/*\
title: $:/plugins/rimir/work-focus/dates.js
type: application/javascript
module-type: library

Date helpers for work-focus: date expressions, formatting, day differences.
All dates are local calendar days; TW 14/17-digit values are UTC instants.

\*/
"use strict";

var DAYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
var CONFIG_FORMAT = "$:/config/rimir/work-focus/date-format";
var DEFAULT_FORMAT = "YYYY0MM0DD";
var TW_FORMAT = "[UTC]YYYY0MM0DD0hh0mm0ss0XXX";

function midnight(date) {
	return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date, n) {
	return new Date(date.getFullYear(), date.getMonth(), date.getDate() + n);
}

function pad(n, len) {
	var s = String(n);
	while(s.length < len) { s = "0" + s; }
	return s;
}

// Local calendar day of a value: Date (local midnight) or null.
function dayOf(value) {
	var v = String(value === undefined || value === null ? "" : value).trim(), d;
	if(/^\d{8}$/.test(v)) {
		d = new Date(+v.slice(0, 4), +v.slice(4, 6) - 1, +v.slice(6, 8));
		// reject overflowed dates such as 20261340
		if(d.getFullYear() !== +v.slice(0, 4) || d.getMonth() !== +v.slice(4, 6) - 1 || d.getDate() !== +v.slice(6, 8)) {
			return null;
		}
		return d;
	}
	if(/^(\d{14}|\d{17})$/.test(v)) {
		d = $tw.utils.parseDate(v);
		return d && !isNaN(d.getTime()) ? midnight(d) : null;
	}
	return null;
}

// expr: today | +Nd | -Nd | +Nw | mon..sun (next such day, never today) | YYYYMMDD
exports.resolve = function(expr, now) {
	var e = String(expr === undefined || expr === null ? "" : expr).trim().toLowerCase(), m, today = midnight(now), delta;
	if(e === "today") {
		return today;
	}
	m = /^([+-])(\d+)([dw])$/.exec(e);
	if(m) {
		return addDays(today, (m[1] === "-" ? -1 : 1) * (+m[2]) * (m[3] === "w" ? 7 : 1));
	}
	m = DAYS.indexOf(e);
	if(m >= 0) {
		delta = (m - today.getDay() + 7) % 7;
		return addDays(today, delta === 0 ? 7 : delta);
	}
	if(/^\d{8}$/.test(e)) {
		return dayOf(e);
	}
	return null;
};

// Format date in the shape of sample (8 digits: YYYYMMDD; 14/17 digits: TW date; else config format).
exports.format = function(date, sample, wiki) {
	var s = String(sample === undefined || sample === null ? "" : sample).trim(), fmt;
	if(/^\d{8}$/.test(s)) {
		return pad(date.getFullYear(), 4) + pad(date.getMonth() + 1, 2) + pad(date.getDate(), 2);
	}
	if(/^(\d{14}|\d{17})$/.test(s)) {
		return $tw.utils.formatDateString(date, TW_FORMAT);
	}
	fmt = ((wiki || $tw.wiki).getTiddlerText(CONFIG_FORMAT) || "").trim() || DEFAULT_FORMAT;
	return $tw.utils.formatDateString(date, fmt);
};

// Whole days from local today to the value's calendar day; null if unparsable.
exports.daysFrom = function(value, now) {
	var d = dayOf(value), t = midnight(now);
	if(!d) {
		return null;
	}
	return Math.round((Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) - Date.UTC(t.getFullYear(), t.getMonth(), t.getDate())) / 86400000);
};
","type":"application/javascript","module-type":"library"},"$:/plugins/rimir/work-focus/doc/architecture":{"title":"$:/plugins/rimir/work-focus/doc/architecture","created":"20261106120000000","modified":"20261106120000000","rdt.hub-category":"tools","rdt.hub-category-name":"Tools","rdt.hub-order":"5","rdt.order":"2","rdt.plugin-key":"work-focus","rdt.plugin-name":"work focus","rdt.plugin-subtitle":"Dock with attention counts and a drag action ring","rdt.section":"Architecture","type":"text/vnd.tiddlywiki","text":"<$transclude $tiddler="$:/plugins/rimir/doc-template/templates/page">
<$fill $name="body">

!! Pieces

|!Piece |!What it does |
|`dates.js`, `date-operators.js` |Date expressions (`today`, `+1d`, `mon`, …), formatting, day differences. Filter operators `wf-date` and `wf-days` |
|`check.js`, `action-wf-check.js` |Runs every area filter once (first match wins), applies mutes, writes the snapshot. `<$action-wf-check/>`. Also the shared filter helpers: `runFilter` (a throw or a `Filter Error: …` result is an error, never an item) and `globalWidget`/`importWidget` (filters run under `\import [subfilter{$:/core/config/GlobalImportFilter}]`, like the page template) |
|`startup-check.tid` |Check on reload (`$:/tags/StartupAction/Browser`) |
|`actions.js` |Which tiles and groups the ring shows for one item (filters see the global and the engine functions); builds and runs an action (`wf.requires` checked first) |
|`ring-layer.js`, `ring-geometry.js` |The pointer gesture and the ring: plain DOM, laid out once per arc |
|`click-outside.js` |Startup module: a click outside dock and panel closes the panel |
|`engine.tid` |Shared `\function`s and `\procedure`s for dock, panel and item |
|`layer.tid`, `dock.tid`, `panel.tid`, `item.tid` |Page template layer, closed strip, open panel, one row |
|`styles.tid`, `config/*`, `info/*`, `recipes/*`, `groups/*`, `actions/*` |Styles, defaults, shipped parts |

!! Data flow

# A check runs the area filters in tag order. An item goes to the first area that matches. Muted items go to the muted list.
# The result is one JSON tiddler, the //snapshot// (`$:/temp/rimir/work-focus/snapshot`). Dock and panel only read it.
# A drag asks `actions.select` for the ring: every action whose filter returns something for this item, grouped by `wf.group`.
# A release runs the action string with the item's variables, then writes an //acted mark// and checks again.

!! State tiddlers

|!Tiddler |!Content |
|`$:/temp/rimir/work-focus/snapshot` |`{"checked", "areas": {area: [items]}, "muted": [items], "errors": {area: message}}` |
|`$:/temp/rimir/work-focus/acted` |`{item: {"area", "mark"}}`; cleared by a reload or ↻ |
|`$:/rimir/work-focus/mutes` |`{item: "YYYYMMDD"}`, saved with the wiki (not under `$:/state/`, which TW does not sync): the day the item shows again |
|`$:/temp/rimir/work-focus/open` |`yes` while the panel is open |
|`$:/temp/rimir/work-focus/more/<area>` |`yes` after "+ N more" was clicked |
|`$:/temp/rimir/work-focus/show-muted` |`yes` while the muted list is shown |
|`$:/state/rimir/work-focus/tab` |The active tab (per session; not saved) |

!! Limits built in

At most 6 groups on the first ring (the rest under "⋯ More") and 3 levels of nesting.

</$fill>
</$transclude>
"},"$:/plugins/rimir/work-focus/doc/dev-workflow":{"title":"$:/plugins/rimir/work-focus/doc/dev-workflow","created":"20261106120000000","modified":"20261106120000000","rdt.hub-category":"tools","rdt.hub-category-name":"Tools","rdt.hub-order":"5","rdt.order":"3","rdt.plugin-key":"work-focus","rdt.plugin-name":"work focus","rdt.plugin-subtitle":"Dock with attention counts and a drag action ring","rdt.section":"Dev Workflow","type":"text/vnd.tiddlywiki","text":"<$transclude $tiddler="$:/plugins/rimir/doc-template/templates/page">
<$fill $name="body">

!! Restart rules

|!Change |!Needs |
|JS modules (`click-outside.js`, `ring-layer.js`, `date-operators.js`, `check.js`, `actions.js`, …) |Server restart, then reload |
|Areas, groups, actions, recipes, info parts, config |Nothing for the definitions; run ↻ to see areas change |
|`styles.tid`, `engine.tid`, `dock.tid`, `panel.tid` |Reload (they are normal tiddlers) |

!! Tests

```
bin/tw test work-focus          # Jasmine: dates, check, actions, run, ring geometry
bin/tw test:e2e work-focus      # Playwright: dock, panel, drag, ring, mutes
```

!! Adding a recipe, group or action

# Create a tiddler with the right tag (see //Reference//). Use the same title as a shipped one to override it.
# Reload. The next drag shows it. Nothing else to register.

!! Debugging

* The snapshot tiddler shows what the last check saw; `errors` names a broken area filter.
* A drag that opens no ring means no action matched the item: check the action's `wf.filter` and that `wf.group` is set.
* `bin/tw test work-focus` runs the check and the actions without a browser.

</$fill>
</$transclude>
"},"$:/plugins/rimir/work-focus/doc/examples":{"title":"$:/plugins/rimir/work-focus/doc/examples","created":"20261106120000000","modified":"20261106120000000","rdt.hub-category":"tools","rdt.hub-category-name":"Tools","rdt.hub-order":"5","rdt.order":"4","rdt.plugin-key":"work-focus","rdt.plugin-name":"work focus","rdt.plugin-subtitle":"Dock with attention counts and a drag action ring","rdt.section":"Examples","type":"text/vnd.tiddlywiki","text":"<$transclude $tiddler="$:/plugins/rimir/doc-template/templates/page">
<$fill $name="body">

!! An overdue area

```
title: $:/config/rimir/work-focus/areas/overdue
tags: $:/tags/rimir/work-focus/area
caption: Overdue
wf.level: alert
wf.date-field: due-date
wf.info: date-relative field:parent
wf.when-past: overdue <<n>>d
wf.filter: [has[due-date]!has[completed-date]] :filter[get[due-date]wf-days[]compare:integer:lt[0]]
```

`wf.info` lists the parts shown under each item: `date-relative`, `date-relative:<field>` (another date field, worded by `wf.when-past.<field>` etc., e.g. `wf.when-future.due-date: due in <<n>>d`), `modified-ago` and `field:<name>`. Several areas can share a tab (`wf.tab`).

!! Status area and a "Done" action

An action that only exists where it makes sense. `<area>` is the area tiddler's title.

```
title: $:/config/rimir/work-focus/actions/done
tags: $:/tags/rimir/work-focus/action
caption: Done
wf.group: status
wf.icon: ✓
wf.filter: [<area>!match[$:/config/rimir/work-focus/areas/plan]]
wf.mark: ✓ done

<$action-setfield $tiddler=<<item>> completed-date={{{ [wf-date[today]] }}}/>
```

!! Your own tiles

Tile values come from `wf.tiles`, a filter. Values with `+` or `-` must be bracketed.

```
wf.tiles: [[today]] [[+1d]] [[+3d]] [[mon]]
```

!! Set a field with the shipped recipe

```
title: $:/config/rimir/work-focus/actions/waiting
tags: $:/tags/rimir/work-focus/action
caption: Waiting
wf.group: status
wf.recipe: set-field
wf.field: status
wf.value: waiting
```

!! Replace a shipped action

Make a tiddler with the same title as the shipped one, e.g. `$:/plugins/rimir/work-focus/actions/day-strip`. Yours wins over the plugin's shadow. To hide one, set `wf.hidden: yes`; to replace it by another action, name it in that action's `wf.replaces`.

</$fill>
</$transclude>
"},"$:/plugins/rimir/work-focus/doc/faq":{"title":"$:/plugins/rimir/work-focus/doc/faq","created":"20261106120000000","modified":"20261106120000000","rdt.hub-category":"tools","rdt.hub-category-name":"Tools","rdt.hub-order":"5","rdt.order":"5","rdt.plugin-key":"work-focus","rdt.plugin-name":"work focus","rdt.plugin-subtitle":"Dock with attention counts and a drag action ring","rdt.section":"FAQ","type":"text/vnd.tiddlywiki","text":"<$transclude $tiddler="$:/plugins/rimir/doc-template/templates/page">
<$fill $name="body">

!! Q: I changed a date and the count did not change.

The counts are a snapshot. Click ↻ or reload. This is on purpose: nothing runs while you edit.

!! Q: An item I expected is missing.

It may sit in an earlier area (first match wins), be muted (see the footer of the panel), or have a blank or non-date value in the area's date field (`wf-days` drops those).

!! Q: The dock shows `!`.

The area filter is broken. Hover the `!` to see the error. The other areas still work.

!! Q: I drag a row and no ring opens.

No action matched this item. An action needs `wf.group`, and its `wf.filter` must return something for the item. Without a filter it always matches.

!! Q: An action has no tile for a value like `+1d`.

Values with `+` or `-` must be bracketed in `wf.tiles`: `[[today]] [[+1d]]`.

!! Q: The action failed halfway; is it undone?

No. Actions are not transactional. A failing action shows a notice and leaves no mark, but what it changed before the failure stays.

!! Q: I defined a group or action twice.

With the same `wf.name` (group or recipe) the first one found wins. To override a shipped one, use the same //title// as the shadow; your tiddler then replaces it.

!! Q: Move does the wrong default.

A group's default tile is the group's `wf.default` action. When it has several tiles, `wf.default-value` picks one. Move uses the day strip's `+1d`.

!! Q: Does clicking an item close the panel?

No, so you can triage several. A click outside closes it, and that click still reaches what is underneath.

!! Q: I installed it and nothing changed.

JS modules need a server restart (`click-outside.js`, `ring-layer.js`, `date-operators.js`, …).

!! Q: The dock is hidden behind the sidebar button.

At `top-right` it can sit under the Vanilla sidebar toggle. Use another corner or move the dock.

!! Q: Tiles are cut off on a small window.

With 5 or 6 groups, a viewport of about 440 px height or less can clamp tiles. Use a taller window.

</$fill>
</$transclude>
"},"$:/plugins/rimir/work-focus/doc/overview":{"title":"$:/plugins/rimir/work-focus/doc/overview","created":"20261106120000000","modified":"20261106120000000","rdt.hub-category":"tools","rdt.hub-category-name":"Tools","rdt.hub-order":"5","rdt.order":"1","rdt.plugin-key":"work-focus","rdt.plugin-name":"work focus","rdt.plugin-subtitle":"Dock with attention counts and a drag action ring","rdt.section":"Overview","type":"text/vnd.tiddlywiki","text":"<$transclude $tiddler="$:/plugins/rimir/doc-template/templates/page">
<$fill $name="body">

!! What it does

A dock in a corner of the page shows how many things need you. Each count is an //area//: a config tiddler with a filter, for example "tasks overdue", "due today", "started". Click the dock and a panel lists the items. Press an item and drag it sideways: a half ring of action tiles opens. Hover a group (Move, Mute, Status, …) to fan out its tiles, release on one to run it. The item is not opened.

The plugin knows nothing about your data. Areas, extra actions and extra groups are config tiddlers in your wiki.

!! How you use it

# The dock shows one pill per area that has items (alert, then warning, then hint) and the time of the last check. ↻ checks again.
# Click the dock: the panel opens. Tabs appear when areas name different tabs. An area shows 5 items, then "+ N more".
# Click an item to open it. The panel stays open, so you can triage.
# Press an item, drag more than 5 pixels (touch: hold 400 ms, then drag). The ring opens on the side of the panel that faces free space.
# Hover a group for 150 ms: its tiles fan out. Release on a tile to run it, or on a group to run its default tile. Esc, release elsewhere, or losing the window cancels.
# The item stays in the panel with a mark ("→ Mon 9", "🔕 until Mon 9") until the next check.
# Click outside the panel to close it. Esc closes it too.

!! Counts are a snapshot

The area filters run on reload, on ↻ and after an action. They never run while you edit, so the dock costs nothing while you type. Edit a date and the counts stay until you check again.

!! Where the configuration lives

|!What |!Where |
|Areas |tiddlers tagged `$:/tags/rimir/work-focus/area` |
|Groups of the ring |tag `$:/tags/rimir/work-focus/group` |
|Actions (tiles) |tag `$:/tags/rimir/work-focus/action` |
|Recipes (action templates) |tag `$:/tags/rimir/work-focus/recipe` |
|Info parts (lines under an item) |tag `$:/tags/rimir/work-focus/info-part` |
|Settings |`$:/config/rimir/work-focus/*` (see the settings tab) |

See //Reference// for every field and //Examples// for ready configurations.

</$fill>
</$transclude>
"},"$:/plugins/rimir/work-focus/doc/reference":{"title":"$:/plugins/rimir/work-focus/doc/reference","created":"20261106120000000","modified":"20261106120000000","rdt.hub-category":"tools","rdt.hub-category-name":"Tools","rdt.hub-order":"5","rdt.order":"6","rdt.plugin-key":"work-focus","rdt.plugin-name":"work focus","rdt.plugin-subtitle":"Dock with attention counts and a drag action ring","rdt.section":"Reference","type":"text/vnd.tiddlywiki","text":"<$transclude $tiddler="$:/plugins/rimir/doc-template/templates/page">
<$fill $name="body">

!! Configuration

|!Tiddler |!Default |!Meaning |
|`$:/config/rimir/work-focus/enabled` |`yes` |`no` removes the dock and the ring |
|`$:/config/rimir/work-focus/position` |`top-left` |`top-left`, `top-right`, `bottom-left`, `bottom-right` |
|`$:/config/rimir/work-focus/date-format` |`YYYY0MM0DD` |Format `wf-date` writes when the field has no sample value. A field that already holds 8 digits or a TW date keeps its shape |
|`$:/config/rimir/work-focus/section-limit` |`5` |Items per area before "+ N more" |

!! Area (tag `$:/tags/rimir/work-focus/area`)

Order = tag order. The first area whose filter returns an item claims it. Drafts are never areas or items. Area filters see the global functions and macros (`$:/tags/Global`, `$:/tags/Macro`), as on the page. A filter that throws or reports `Filter Error: …` shows `!` with the message as tooltip.

|!Field |!Meaning |
|`caption` |Name in dock tooltip and panel |
|`wf.filter` |Filter returning the item titles |
|`wf.level` |`alert`, `warning` or `hint` (default `hint`). Dock order: alert, warning, hint |
|`wf.date-field` |Field the info parts and date actions use (variable `date-field`) |
|`wf.tab` |Tab name; blank = "General" |
|`wf.info` |Space separated parts: `date-relative`, `date-relative:<field>`, `modified-ago`, `field:<name>` |
|`wf.when-past`, `wf.when-today`, `wf.when-future` |Wikitext for `date-relative`; `<<n>>` = number of days. Defaults `<<n>>d ago`, `today`, `in <<n>>d` |
|`wf.when-past.<field>`, `wf.when-today.<field>`, `wf.when-future.<field>` |Wording for `date-relative:<field>` (e.g. `wf.when-future.due-date: due in <<n>>d`); same defaults |

!! Group (tag `$:/tags/rimir/work-focus/group`)

|!Field |!Meaning |
|`wf.name` |Key that actions name in `wf.group`. The first group with a name wins |
|`caption`, `wf.icon`, `wf.order` |Label, icon, sort order |
|`wf.parent` |Name of the parent group (3 levels at most) |
|`wf.default` |Action run when you release on the group itself |
|`wf.default-value` |Tile value of that action to run (Move: `+1d`) |

Shipped groups: `move`, `mute`, `status`, `create`, `open`. A group without tiles is not shown (`create` has no shipped action).

!! Action (tag `$:/tags/rimir/work-focus/action`)

|!Field |!Meaning |
|`caption`, `wf.icon`, `wf.order` |Tile text, icon, order |
|`wf.group` |Group name. ''Without it the action is not shown'' |
|`wf.filter` |The action applies when the result is ''non-empty''. Source = the item. A broken filter (or `Filter Error: …`) means no match. Blank = always |
|`wf.recipe` |Recipe name. Blank: the tiddler's text is the action string |
|`wf.tiles` |Filter giving tile values (one tile each). Bracket `+`/`-`: `[[today]] [[+1d]]`. `[function[wf.distinct-days],[today +1d mon]]` drops a date expression that falls on an earlier one's day |
|`wf.tile-label`, `wf.tile-sub` |Wikitext for a tile's label and sub line (`<<value>>`) |
|`wf.hint` |Wikitext shown while hovering a tile; blank: the recipe's |
|`wf.mark` |Wikitext for the acted mark; blank: the recipe's, then the tile caption |
|`wf.no-mark` |`yes`: no mark (Open) |
|`wf.hidden` |`yes`: never shown |
|`wf.replaces` |Titles of actions this one hides while it matches |
|`wf.requires` |Filter (engine functions available) whose first value must be non-blank, else nothing runs: no mark, no check, notification `wf.requires-message` (default "Nothing to do"). Blank: the recipe's |
|recipe parameters |`wf.field`, `wf.to`, `wf.until`, `wf.value`, `wf.title`, `wf.fields`, `wf.tag`, `wf.mode` — see the recipes |

Variables in filters, hints, marks, tile labels and action strings: `item`, `area`, `date-field`, `value`, `action`; `currentTiddler` = `item`. They also see the global functions and macros and the `wf.*` engine functions. Draft actions, groups and recipes are ignored.

!! Recipe (tag `$:/tags/rimir/work-focus/recipe`)

`wf.name`, `caption`, `wf.mark`, `wf.hint`, `wf.deferred` (`yes`: the action sets its own mark later), `wf.requires` / `wf.requires-message` (see Action), text = the action string.

|!Shipped |!Parameters |
|`move-date` |`wf.field` (default: the area's date field), `wf.to` (default: the tile value). No field: fails with "no field to set" |
|`mute` |`wf.until` (default: the tile value) |
|`open` |none |
|`set-field` |`wf.field`, `wf.value`. Blank `wf.field`: fails with "no field to set" |
|`tag` |`wf.tag`, `wf.mode` (`add` or `remove`) |
|`create` |`wf.title` (filter), `wf.fields` (JSON: field name to filter) |

!! Shipped actions

`actions/day-strip` (Move date: Today, Tmrw, Mon, Tue, +1w), `actions/mute` (2 days, Mon, 1 week), `actions/open`. A tile on the same day as an earlier one is left out (Sunday: no Mon, it is Tmrw; Monday: no Tue and no +1w). Tile labels: Today, Tmrw, then weekday; sub line = the date only (`0DD mmm`). Dates in hints use `ddd DD mmm`.

!! Date expressions

`today`, `+Nd`, `-Nd`, `+Nw`, `mon` … `sun` (the next such day, never today), `YYYYMMDD`.

!! Filter operators

|!Operator |!Result |
|`[wf-date[<expr>],[<sample>]]` |One date string in the shape of the sample |
|`[<dates>wf-days[]]` |Whole days from today per input; blank and non-dates dropped |

!! Info parts (tag `$:/tags/rimir/work-focus/info-part`)

`wf.name` is the token in `wf.info`; the text is wikitext with `item`, `area`, `date-field`, `param` (the part after `:`).

|!Shipped |!Shows |
|`date-relative` |The area's date field relative to today (`wf.when-*` wording) |
|`date-relative:<field>` |That field instead, with `wf.when-*.<field>` wording |
|`modified-ago` |"changed 3d ago" |
|`field:<name>` |The field's value; a tiddler (or a title list) by caption |

</$fill>
</$transclude>
